{
  "arguments": [
    {
      "stance": "contra",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "Het gaat niet om een afzwakking, maar om het stuk regelgeving dat niet uitvoerbaar is. Dat zou er ook daadwerkelijk toe leiden dat huishoudens in Europa deze winter geen gas hebben.",
      "quote_context": "Kritiek op de uitvoerbaarheid van de Methaanverordening en het risico op gasleveringsproblemen.",
