    {
      "stance": "contra",
      "typology": "factual",
      "ander_onderwerp": null,
      "quote_text": "We moeten er natuurlijk wel voor zorgen dat de manier waarop de verordening gaat werken ook uitvoerbaar is. Ik denk dat ook mevrouw Van Oosterhout geen hele grote risico's zou willen nemen met de leveringszekerheid van huishoudens in Nederland. Daarom hebben we nu echt de gesprekken daarover in Brussel nog nodig.",
      "quote_context": "Argumentatie voor onderhandelingen in Brussel om risico's voor leveringszekerheid te beperken.",
      "claims": []
    }
